const refreshIntervals = [0, 10, 15, 30, 60];

function LogRefreshControl({jsx, hooks, t, storageKey, defaultSeconds=0,
  onRefresh, isBlocked, pauseAuto=false, updated='', preview}) {
  const {useEffect,useId,useRef,useState} = hooks;
  const [seconds,setSeconds] = useState(()=>{
    if(preview) return preview.seconds;
    try {
      const saved = localStorage.getItem(storageKey);
      if(saved !== null && refreshIntervals.includes(Number(saved))) return Number(saved);
    } catch {}
    return defaultSeconds;
  });
  const [open,setOpen] = useState(Boolean(preview?.open));
  const [phase,setPhase] = useState(preview?.phase || 'idle');
  const [remaining,setRemaining] = useState(seconds);
  const [paused,setPaused] = useState(false);
  const root = useRef(null), trigger = useRef(null), menu = useRef(null);
  const latest = useRef(null), running = useRef(false), mounted = useRef(false);
  const deadline = useRef(0), focusIndex = useRef(0);
  const menuId = useId();
  latest.current = {onRefresh,isBlocked,pauseAuto,open,seconds};
  const phrase = (key,values)=>Object.entries(values).reduce(
    (label,[name,value])=>label.replace('{'+name+'}',String(value)),t(key));
  const intervalLabel = value=>phrase('Every {seconds} seconds',{seconds:value});

  function isPaused() {
    return document.visibilityState !== 'visible' || latest.current.open ||
      Boolean(document.querySelector('.audit-time-range[open], .ops-drawer[open], .log-table details[open], .audit-table details[open], .logging-workspace tbody details[open]'));
  }
  async function refresh() {
    if(running.current || latest.current.isBlocked?.()) return;
    running.current = true;
    setPhase('refreshing');
    try {
      const ok = await latest.current.onRefresh();
      if(mounted.current) setPhase(ok === false ? 'error' : 'idle');
    } catch {
      if(mounted.current) setPhase('error');
    } finally {
      running.current = false;
      deadline.current = Date.now() + latest.current.seconds * 1000;
      if(mounted.current) setRemaining(latest.current.seconds);
    }
  }
  useEffect(()=>{mounted.current=true;return()=>{mounted.current=false;};},[]);
  useEffect(()=>{
    if(preview || !seconds) return;
    const reset = ()=>{deadline.current=Date.now()+seconds*1000;setRemaining(seconds);};
    reset();
    const timer = window.setInterval(()=>{
      const blocked = Boolean(latest.current.pauseAuto || isPaused() || latest.current.isBlocked?.());
      setPaused(blocked);
      if(blocked || running.current){reset();return;}
      const next = Math.max(0,Math.ceil((deadline.current-Date.now())/1000));
      setRemaining(next);
      if(!next) void refresh();
    },250);
    document.addEventListener('visibilitychange',reset);
    return ()=>{window.clearInterval(timer);document.removeEventListener('visibilitychange',reset);};
  },[seconds]);
  useEffect(()=>{
    if(!open || preview) return;
    const focus = ()=>menu.current?.querySelectorAll('[role="menuitemradio"]')[focusIndex.current]?.focus();
    focus();
    function outside(event){if(!root.current?.contains(event.target))setOpen(false);}
    document.addEventListener('pointerdown',outside);
    document.addEventListener('focusin',outside);
    return ()=>{
      document.removeEventListener('pointerdown',outside);
      document.removeEventListener('focusin',outside);
    };
  },[open]);

  function close() {setOpen(false);trigger.current?.focus();}
  function choose(value) {
    setSeconds(value);
    setRemaining(value);
    try {localStorage.setItem(storageKey,String(value));} catch {}
    close();
  }
  function openMenu(index) {focusIndex.current=index;setOpen(true);}
  function navigate(event,index) {
    if(event.key==='Escape'){event.preventDefault();close();return;}
    const target = {ArrowDown:(index+1)%5,ArrowUp:(index+4)%5,Home:0,End:4}[event.key];
    if(target===undefined)return;
    event.preventDefault();
    menu.current?.querySelectorAll('[role="menuitemradio"]')[target]?.focus();
  }

  const paths = {
    refresh:'M20 7v5h-5 M4 17v-5h5 M6 7a7 7 0 0 1 11.5-1L20 9 M4 15l2.5 3A7 7 0 0 0 18 17',
    chevron:'m6 9 6 6 6-6',check:'m5 12 4 4L19 6',pause:'M9 5v14 M15 5v14',
    clock:'M12 7v5l3 2 M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18Z',
  };
  function icon(name,key) {
    return jsx('svg',{viewBox:'0 0 24 24',width:16,height:16,fill:'none',stroke:'currentColor',
      strokeWidth:1.8,strokeLinecap:'round',strokeLinejoin:'round','aria-hidden':true,
      className:'refresh-icon refresh-icon-'+name,children:jsx('path',{d:paths[name]})},key);
  }

  const active = seconds > 0;
  const label = active?phrase('Every {seconds}s',{seconds}):t('Auto-refresh: Off');
  const title = active && (paused || pauseAuto)?t('Auto-refresh paused'):active?phrase('Auto-refresh every {seconds} seconds · next in {remaining}s',{seconds,remaining}):label;
  return jsx('div',{className:'log-refresh-toolbar',children:[
    updated&&jsx('span',{className:'log-refresh-updated',children:t('Last updated:')+' '+updated},'updated'),
    jsx('div',{ref:root,className:'log-refresh-control','data-enabled':active,'data-phase':phase,'data-paused':paused||pauseAuto,
      children:[
        jsx('div',{className:'log-refresh-split',children:[
          jsx('button',{type:'button',className:'log-refresh-now',onClick:refresh,'data-refresh-tip':title,
            'aria-label':t('Refresh')+' · '+label,'aria-disabled':phase==='refreshing','aria-busy':phase==='refreshing',
            children:[icon('refresh','refresh'),jsx('span',{className:'refresh-label',children:label},'label'),
              jsx('span',{className:'refresh-short-label','aria-hidden':true,children:active?seconds+'s':t('Off')},'short')]},'refresh'),
          jsx('button',{ref:trigger,type:'button',className:'log-refresh-select',
            'aria-label':t('Refresh interval'),'aria-haspopup':'menu','aria-expanded':open,'aria-controls':open?menuId:undefined,
            onClick:()=>open?close():openMenu(refreshIntervals.indexOf(seconds)),
            onKeyDown:event=>{
              if(event.key==='Escape'&&open){event.preventDefault();close();}
              if(['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();openMenu(event.key==='ArrowDown'?0:4);}
            },children:icon('chevron')},'interval'),
        ]},'split'),
        phase==='error'&&jsx('span',{className:'log-refresh-error',tabIndex:0,role:'status','data-refresh-tip':t('Last refresh failed'),
          children:jsx('span',{className:'refresh-sr-only',children:t('Last refresh failed')})},'error'),
        open&&jsx('div',{className:'log-refresh-menu',children:[
          jsx('div',{className:'log-refresh-heading',children:t('Refresh interval')},'heading'),
          jsx('div',{id:menuId,ref:menu,role:'menu','aria-label':t('Refresh interval'),
            children:refreshIntervals.map((value,index)=>jsx('button',{
              type:'button',role:'menuitemradio',tabIndex:-1,'aria-checked':seconds===value,
              'data-preview-hover':preview?.hover===value||undefined,
              onClick:()=>choose(value),onKeyDown:event=>navigate(event,index),
              children:[icon(value?'clock':'pause','type'),jsx('span',{children:value?intervalLabel(value):t('Off')},'label'),
                seconds===value&&icon('check','check')],
            },value))},'items'),
        ]},'menu'),
      ]},'control'),
  ]});
}

function logPageControls({jsx,jsxs,t,page,last,count,size,busy,onPage,onSize}) {
  const first=count?(page-1)*size+1:0;
  const numbers=[...new Set([1,page-2,page-1,page,page+1,page+2,last])]
    .filter(number=>number>=1&&number<=last).sort((a,b)=>a-b);
  const go=(number,label,content,disabled=false)=>jsx('button',{
    type:'button',className:number===page?'log-page-current':'secondary',
    disabled:busy||disabled,'aria-label':label,
    'aria-current':number===page?'page':undefined,
    onClick:()=>{if(number!==page)onPage(number);},children:content,
  });
  return jsxs('div',{className:'log-page-controls',children:[
    jsxs('div',{className:'log-page-summary',children:[
      jsx('span',{children:t('Showing')+' '+first+'–'+(count?first+count-1:0)}),
      jsx('select',{'aria-label':t('Rows per page'),value:size,disabled:busy,
        onChange:event=>onSize(Number(event.target.value)),
        children:[10,20,50,100].map(value=>jsx('option',{value,children:value+' '+t('per page')},value)),
      }),
    ]}),
    last>1&&jsxs('nav',{'aria-label':t('Pagination'),className:'log-page-buttons',children:[
      go(page-1,t('Previous page'),'‹',page===1),
      ...numbers.map((number,index)=>jsxs('span',{children:[
        index>0&&number>numbers[index-1]+1&&jsx('span',{'aria-hidden':true,children:'…'}),
        go(number,t('Page')+' '+number,number),
      ]},number)),
      go(page+1,t('Next page'),'›',page===last),
    ]}),
  ]});
}

function logPageState(previous,page,next,size,preserve) {
  const starts=page===1&&!preserve?[null]:previous.starts.slice(0,page);
  if (next!=null) {
    if (preserve&&previous.starts[page]===next) return {...previous,page,size};
    starts.push(next);
  }
  return {page,starts,size};
}

function dashboardServiceRow({jsx,jsxs,t,snapshot,service,formatTime}) {
  const name={app:'TACACS+',admin:'Web Admin',proxy:'HTTPS Proxy',postgres:'PostgreSQL'}[service];
  const status=snapshot?.services?.[service];
  const online=['healthy','unhealthy','starting','running'].includes(status);
  const offline=['exited','created','paused','restarting','dead','removing','missing'].includes(status);
  const tone=online?'good':offline?'bad':'neutral';
  const started=online?snapshot.service_started_at?.[service]:undefined;
  const seconds=Math.floor((Date.parse(snapshot?.observed_at)-Date.parse(started))/1000);
  const elapsed = seconds >= 86400 ? Math.floor(seconds / 86400) + 'd'
    : seconds >= 3600 ? Math.floor(seconds / 3600) + 'h'
    : seconds >= 60 ? Math.floor(seconds / 60) + 'm'
    : seconds + 's';
  const latency=online?snapshot.probe_latency_ms?.[service]:undefined;
  const probe=service==='app'?'TCP/49':'HTTPS/8443';
  const healthNote=status==='unhealthy'?t('Unhealthy'):status==='starting'?t('Starting'):undefined;
  return jsxs('li',{className:'dash-service-row',children:[
    jsx('i',{className:'dash-dot '+tone,'aria-hidden':'true'}),
    jsxs('div',{children:[
      jsx('strong',{children:name}),
      jsxs('span',{className:'dash-service-status '+tone,title:healthNote,children:[
        t(online?'Online':offline?'Offline':'Not currently verified'),
        typeof latency==='number'&&jsx('span',{className:'dash-service-latency',title:probe,children:latency.toFixed(1)+' ms'}),
      ]}),
    ]}),
    seconds>=0&&jsx('span',{className:'dash-service-metrics',title:formatTime(started),children:t('{time} ago').replace('{time}',elapsed)}),
  ]},service);
}

const actionGroups = [
  ['AAA', 'aaa', ['authentication', 'authorization', 'accounting']],
  ['Identity', 'identity', ['create', 'update', 'delete', 'enable', 'disable']],
  ['Identity group', 'identity-group', ['create', 'rename', 'delete']],
  ['Device', 'device', ['create', 'update', 'delete']],
  ['Device group', 'device-group', ['create', 'update', 'delete']],
  ['Policy', 'policy', ['discard']],
];

function auditActionCombobox({jsx, jsxs, hooks, t, value, onChange, disabled = false}) {
  const {useEffect, useId, useRef, useState} = hooks;
  const id = useId();
  const trigger = useRef(null), panel = useRef(null), search = useRef(null);
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [cursor, setCursor] = useState(null);
  const needle = query.trim().toLowerCase();
  const groups = actionGroups.map(([label, prefix, verbs]) => [
    label, verbs.map(verb => ({verb, key:prefix + '.' + verb}))
      .filter(item => item.key.includes(needle) || t(item.verb).toLowerCase().includes(needle)),
  ]).filter(([,items]) => items.length);
  const all = {verb:'All actions', key:''};
  const options = [...(needle ? [] : [all]), ...groups.flatMap(([,items]) => items)];
  const active = options.find(item => item.key === cursor) ??
    options.find(item => item.key === value) ?? options[0];
  const optionId = key => id + '-action-' + (key || 'all');

  function position() {
    const element = panel.current;
    if (!element?.matches(':popover-open')) return;
    const anchor = trigger.current.parentElement.getBoundingClientRect();
    const viewport = document.documentElement;
    const width = Math.min(Math.max(anchor.width,280),viewport.clientWidth-16);
    const below = viewport.clientHeight-anchor.bottom-12;
    const above = anchor.top-12;
    const flip = below < 360 && above > below;
    element.style.setProperty('--action-width',width+'px');
    element.style.setProperty('--action-left',Math.max(8,Math.min(anchor.left,viewport.clientWidth-width-8))+'px');
    element.style.setProperty('--action-top',flip ? 'auto' : anchor.bottom+4+'px');
    element.style.setProperty('--action-bottom',flip ? viewport.clientHeight-anchor.top+4+'px' : 'auto');
    element.style.setProperty('--action-height',Math.min(360,Math.max(0,flip ? above : below))+'px');
  }

  useEffect(() => {
    if (!open) return;
    window.addEventListener('resize',position);
    window.addEventListener('scroll',position,true);
    return () => {
      window.removeEventListener('resize',position);
      window.removeEventListener('scroll',position,true);
    };
  },[open]);

  function choose(key) {
    onChange(key);
    panel.current.hidePopover();
    trigger.current.focus();
  }

  function keyboard(event) {
    const key = event.key;
    if (!['ArrowDown','ArrowUp','Home','End','Enter','Escape'].includes(key)) return;
    if ((key === 'Home' || key === 'End') && event.shiftKey) return;
    event.preventDefault();
    if (key === 'Escape') { panel.current.hidePopover(); trigger.current.focus(); return; }
    if (key === 'Enter') { if (active) choose(active.key); return; }
    if (!options.length) return;
    const index = options.indexOf(active);
    const next = key === 'Home' ? 0 : key === 'End' ? options.length-1 :
      Math.max(0,Math.min(options.length-1,index+(key === 'ArrowDown' ? 1 : -1)));
    setCursor(options[next].key);
    document.getElementById(optionId(options[next].key))?.scrollIntoView({block:'nearest'});
  }

  function highlight(text) {
    const start = needle ? text.toLowerCase().indexOf(needle) : -1;
    return start < 0 ? text : [
      text.slice(0,start), jsx('mark',{children:text.slice(start,start+needle.length)},'match'),
      text.slice(start+needle.length),
    ];
  }

  function option({verb,key}) {
    return jsxs('div',{
      id:optionId(key), role:'option', 'aria-selected':value === key,
      'data-active':active?.key === key, className:'audit-action-option',
      onMouseDown:event=>event.preventDefault(), onClick:()=>choose(key),
      children:[
        jsx('i',{'aria-hidden':true,'data-verb':verb}),
        jsx('span',{children:highlight(t(verb))}),
        jsx('code',{children:highlight(key)}),
        jsx('span',{'aria-hidden':true,children:value === key ? '\u2713' : ''}),
      ],
    },key);
  }

  return jsxs('div',{className:'audit-action-filter',children:[
    jsx('span',{id:id+'-label',children:t('Event action')}),
    jsxs('div',{className:'audit-action-trigger',children:[
      jsxs('button',{
        type:'button',ref:trigger,disabled,popoverTarget:id+'-panel',
        'aria-haspopup':'listbox','aria-expanded':open,
        'aria-controls':id+'-panel','aria-labelledby':id+'-label '+id+'-value',
        onKeyDown:event=>{
          if (!['ArrowDown','ArrowUp'].includes(event.key)) return;
          event.preventDefault();
          panel.current.showPopover();
        },
        children:[
          jsx('span',{id:id+'-value',className:value ? 'audit-action-key' : '',children:value || t('All actions')}),
          jsx('i',{'aria-hidden':true,className:'audit-action-chevron'}),
        ],
      }),
      value && jsx('button',{type:'button',disabled,className:'audit-action-clear',
        'aria-label':t('Clear event action'),children:'\u00d7',onClick:()=>{onChange('');trigger.current.focus();}}),
    ]}),
    jsxs('div',{id:id+'-panel',popover:'auto',ref:panel,className:'audit-action-panel',
      onToggle:event=>{
        const visible = event.currentTarget.matches(':popover-open');
        setOpen(visible);
        if (visible) {
          setQuery(''); setCursor(value); position(); search.current.focus();
        }
      },
      children:[
        jsxs('div',{className:'audit-action-search',children:[
          jsx('i',{'aria-hidden':true}),
          jsx('input',{
            ref:search,type:'text',role:'combobox','aria-label':t('Search actions'),
            'aria-autocomplete':'list','aria-expanded':open,'aria-controls':id+'-list',
            'aria-activedescendant':open && active ? optionId(active.key) : undefined,
            placeholder:t('Search actions')+'\u2026',value:query,
            onChange:event=>{setQuery(event.target.value);setCursor(null);},onKeyDown:keyboard,
          }),
        ]}),
        jsxs('div',{id:id+'-list',role:'listbox','aria-labelledby':id+'-label',className:'audit-action-list',children:[
          !needle && option(all),
          ...groups.map(([label,items])=>jsxs('div',{role:'group','aria-label':t(label),children:[
            jsx('div',{className:'audit-action-section','aria-hidden':true,children:t(label)}),
            ...items.map(option),
          ]},label)),
        ]}),
        !options.length && jsxs('div',{className:'audit-action-empty',children:[
          jsx('span',{role:'status',children:t('No matching action')}),
          jsx('button',{type:'button',children:t('Clear search'),onClick:()=>{setQuery('');setCursor(null);search.current.focus();}}),
        ]}),
      ],
    }),
  ]});
}

function auditDateTimeControls({jsx, jsxs, label, value, onChange, t, endOfDay = false}) {
  const [date = '', time = endOfDay ? '23:59' : '00:00'] = value.split('T');
  const [hours, minutes] = time.split(':').map(Number);
  const period = hours < 12 ? 'AM' : 'PM';
  const hour = hours % 12 || 12;
  const pad = (number) => String(number).padStart(2, '0');
  function setTime(nextHour, nextMinute, nextPeriod) {
    onChange(date + 'T' + pad(nextHour % 12 + (nextPeriod === 'PM' ? 12 : 0)) + ':' + pad(nextMinute));
  }
  function select(name, selected, choices, change) {
    return jsx('select', {
      'aria-label': label + ' · ' + t(name),
      value: selected,
      disabled: !date,
      onChange: (event) => change(event.target.value),
      children: choices.map((choice) => jsx('option', {value: choice, children: choice}, choice)),
    });
  }
  return jsxs('div', {className: 'audit-date-time', children: [
    jsxs('label', {children: [
      label,
      jsx('input', {
        type: 'date', value: date,
        onClick: (event) => {
          try { event.currentTarget.showPicker?.(); } catch { /* Native control remains usable. */ }
        },
        onChange: (event) => onChange(event.target.value ? event.target.value + 'T' + time : ''),
      }),
    ]}),
    jsxs('div', {className: 'audit-date-time-clock', children: [
      select('Hour', hour, Array.from({length: 12}, (_, index) => index + 1), (next) => setTime(Number(next), minutes, period)),
      select('Minute', pad(minutes), Array.from({length: 60}, (_, index) => pad(index)), (next) => setTime(hour, Number(next), period)),
      select('AM/PM', period, ['AM', 'PM'], (next) => setTime(hour, minutes, next)),
    ]}),
  ]});
}

function auditDateTimeRange({jsx, jsxs, t, since, until, onSince, onUntil}) {
  const day = 86400000;
  const instant = (value) => Date.parse(value + '+07:00');
  const duration = instant(until) - instant(since);
  const error = duration < 0 ? 'Start must precede the end.' :
    duration > 31 * day ? 'The time range cannot exceed 31 days.' : '';
  const format = (value) => {
    if (!value) return '—';
    const [date, time] = value.split('T');
    return date.split('-').reverse().join('/') + ' ' + time;
  };
  const caption = since || until ? format(since) + ' → ' + format(until) : t('Last 24 hours');
  function boundary(label, value, change, defaultTime) {
    const [date, time = defaultTime] = value.split('T');
    return jsxs('div', {className:'audit-boundary', children:[
      jsxs('label', {children:[label, jsx('input', {
        type:'date', value:date,
        onClick:event=>{ try { event.currentTarget.showPicker?.(); } catch {} },
        onChange:event=>change(event.target.value ? event.target.value + 'T' + time : ''),
      })]}),
      jsx('input', {
        type:'text', inputMode:'numeric', maxLength:5, defaultValue:time,
        'aria-label':label + ' HH:mm', pattern:'(?:[01][0-9]|2[0-3]):[0-5][0-9]',
        disabled:!date, required:Boolean(date),
        onBlur:event=>{ if (event.currentTarget.validity.valid && date) change(date + 'T' + event.target.value); },
        onKeyDown:event=>{ if (event.key === 'Enter') { event.preventDefault(); event.currentTarget.blur(); } },
      }, value),
    ]});
  }
  function choose(minutes) {
    const end = Math.floor(Date.now()/60000)*60000;
    const local = (time) => new Date(time + 420*60000).toISOString().slice(0,16);
    onSince(local(end - minutes*60000));
    onUntil(local(end));
  }
  function close(details) {
    details.open = false;
    details.querySelector('summary').focus();
  }
  return jsxs('details', {className:'audit-time-range',
    onKeyDown:event=>{
      if (event.key !== 'Escape' || !event.currentTarget.open) return;
      event.stopPropagation();
      close(event.currentTarget);
    },
    children:[
      jsxs('summary', {children:[
        jsx('span',{children:t('Time range (UTC+07:00)')}),
        jsx('strong',{title:caption,children:caption}),
      ]}),
      jsxs('div',{className:'audit-time-panel',children:[
        jsx('div',{className:'audit-presets',children:[
          ['15 min',15],['1 h',60],['24 h',1440],['7 d',10080],['31 d',44640],
        ].map(([label,minutes])=>jsx('button',{type:'button',className:'secondary',onClick:()=>choose(minutes),children:t(label)},label))}),
        jsxs('div',{className:'audit-boundaries',children:[
          boundary(t('From (UTC+07:00)'),since,onSince,'00:00'),
          boundary(t('To (UTC+07:00)'),until,onUntil,'23:59'),
        ]}),
        error && jsx('p',{className:'error',role:'alert',children:t(error)}),
        jsx('button',{type:'button',disabled:Boolean(error),children:t('Apply'),onClick:event=>{
          const details = event.currentTarget.closest('details');
          const invalid = [...details.querySelectorAll('input')].find(input=>!input.checkValidity());
          if (invalid) { invalid.reportValidity(); return; }
          close(details);
        }}),
      ]}),
    ],
  });
}

